PRAGMA foreign_keys = ON;
CREATE TABLE applicant(id TEXT PRIMARY KEY NOT NULL, display_name TEXT NOT NULL, created_on TEXT NOT NULL);
CREATE TABLE employment(id TEXT PRIMARY KEY NOT NULL, applicant_id TEXT NOT NULL REFERENCES applicant(id), start_on TEXT NOT NULL, end_on TEXT CHECK(end_on > start_on), kind TEXT NOT NULL CHECK(kind IN ('salaried','contract')));
CREATE TABLE income_record(id TEXT PRIMARY KEY NOT NULL, applicant_id TEXT NOT NULL REFERENCES applicant(id), source TEXT NOT NULL CHECK(source IN ('payroll','declared')), effective_on TEXT NOT NULL, monthly INTEGER NOT NULL CHECK(monthly > 0), UNIQUE(applicant_id,source,effective_on));
CREATE TABLE credit_facility(id TEXT PRIMARY KEY NOT NULL, applicant_id TEXT NOT NULL REFERENCES applicant(id), opened_on TEXT NOT NULL, closed_on TEXT CHECK(closed_on > opened_on), balance INTEGER NOT NULL CHECK(balance >= 0), monthly_due INTEGER NOT NULL CHECK(monthly_due >= 0), late_payments INTEGER NOT NULL CHECK(late_payments >= 0));
CREATE TABLE loan_product(id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL UNIQUE, min_principal INTEGER NOT NULL CHECK(min_principal > 0), max_principal INTEGER NOT NULL CHECK(max_principal >= min_principal), annual_bps INTEGER NOT NULL CHECK(annual_bps >= 0), min_term INTEGER NOT NULL CHECK(min_term > 0), max_term INTEGER NOT NULL CHECK(max_term >= min_term), effective_on TEXT NOT NULL);
CREATE TABLE loan_application(id TEXT PRIMARY KEY NOT NULL, applicant_id TEXT NOT NULL REFERENCES applicant(id), product_id TEXT NOT NULL REFERENCES loan_product(id), principal INTEGER NOT NULL CHECK(principal > 0), term INTEGER NOT NULL CHECK(term > 0), submitted_at TEXT NOT NULL, duplicate_of TEXT REFERENCES loan_application(id));
CREATE TABLE document(id TEXT PRIMARY KEY NOT NULL, application_id TEXT NOT NULL REFERENCES loan_application(id), kind TEXT NOT NULL CHECK(kind IN ('identity','income_proof')), UNIQUE(application_id,kind));
CREATE TABLE document_event(id INTEGER PRIMARY KEY, document_id TEXT NOT NULL REFERENCES document(id), status TEXT NOT NULL CHECK(status IN ('missing','received','verified')), recorded_at TEXT NOT NULL);
CREATE TABLE affordability_check(id INTEGER PRIMARY KEY, application_id TEXT NOT NULL REFERENCES loan_application(id), checked_at TEXT NOT NULL, payroll_id TEXT NOT NULL REFERENCES income_record(id), declared_id TEXT NOT NULL REFERENCES income_record(id), employment_id TEXT NOT NULL REFERENCES employment(id), income INTEGER NOT NULL, debt INTEGER NOT NULL, payment INTEGER NOT NULL, dti_bps INTEGER NOT NULL, post_loan_bps INTEGER NOT NULL, residual INTEGER NOT NULL, score INTEGER NOT NULL CHECK(score BETWEEN 300 AND 850), income_conflict INTEGER NOT NULL CHECK(income_conflict IN (0,1)));
CREATE TABLE check_facility(check_id INTEGER NOT NULL REFERENCES affordability_check(id), facility_id TEXT NOT NULL REFERENCES credit_facility(id), PRIMARY KEY(check_id,facility_id));
CREATE TABLE decision(id TEXT PRIMARY KEY NOT NULL, check_id INTEGER NOT NULL UNIQUE REFERENCES affordability_check(id), decided_at TEXT NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN ('approved','rejected','manual_review')), rule TEXT NOT NULL, inputs TEXT NOT NULL CHECK(json_valid(inputs)));
CREATE TABLE repayment_schedule(application_id TEXT NOT NULL REFERENCES loan_application(id), installment INTEGER NOT NULL CHECK(installment > 0), due_on TEXT NOT NULL, principal INTEGER NOT NULL CHECK(principal >= 0), interest INTEGER NOT NULL CHECK(interest >= 0), payment INTEGER NOT NULL CHECK(payment >= 0), remaining INTEGER NOT NULL CHECK(remaining >= 0), PRIMARY KEY(application_id,installment));
CREATE TABLE disbursement(id INTEGER PRIMARY KEY, application_id TEXT NOT NULL UNIQUE REFERENCES loan_application(id), decision_id TEXT NOT NULL UNIQUE REFERENCES decision(id), paid_at TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount > 0));
CREATE INDEX employment_applicant ON employment(applicant_id,start_on);
CREATE INDEX income_applicant ON income_record(applicant_id,effective_on);
CREATE INDEX facility_applicant ON credit_facility(applicant_id,opened_on);
CREATE INDEX applications_by_customer ON loan_application(applicant_id,product_id);
CREATE INDEX documents_by_application ON document(application_id);
CREATE INDEX document_history ON document_event(document_id,recorded_at);
CREATE INDEX checks_by_application ON affordability_check(application_id);
